def filter_nulls(data):
    return [item for item in data if item is not None]


def normalize_strings(data):
    return [item.strip().lower() if isinstance(item, str) else item for item in data]


def deduplicate(data):
    seen = set()
    result = []
    for item in data:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def sort_results(data):
    return sorted(data)


def pipe(value, functions):
    for func in functions:
        value = func(value)
    return value


class Pipeline:
    def __init__(self, data):
        self.data = data

    def run(self):
        return pipe(
            self.data,
            [
                filter_nulls,
                normalize_strings,
                deduplicate,
                sort_results,
            ],
        )
